{"explanation":"Completing the square turns x² + 6x into a perfect square by thinking geometrically: x² is a square of side x, and 6x is a rectangle we split into two 3x strips placed along two sides of the square. The only thing missing from a full (x + 3) × (x + 3) square is the little 3 × 3 corner, which has area 9. So x² + 6x + 9 = (x + 3)² — use the slider to change x and watch the area model stay balanced, and toggle the corner piece to see why we add 9.","manimCode":"const A = [-3.5, -2.8];
const s = 0.6;
let curX = 2;
const p = (mx, my) => [A[0] + s * mx, A[1] + s * my, 0];

// --- Shapes (Polygons so vertices can update live) ---
const square = new Polygon({ vertices: [p(0,0), p(2,0), p(2,2), p(0,2)], color: BLUE });
square.setFill(BLUE_E, 0.55);
square.setStrokeWidth(3);

const rightRect = new Polygon({ vertices: [p(2,0), p(5,0), p(5,2), p(2,2)], color: GREEN });
rightRect.setFill(GREEN_E, 0.55);
rightRect.setStrokeWidth(3);

const topRect = new Polygon({ vertices: [p(0,2), p(2,2), p(2,5), p(0,5)], color: ORANGE });
topRect.setFill(ORANGE, 0.4);
topRect.setStrokeWidth(3);

const corner = new Polygon({ vertices: [p(2,2), p(5,2), p(5,5), p(2,5)], color: RED });
corner.setFill(RED_E, 0.45);
corner.setStrokeWidth(3);

const outline = new Polygon({ vertices: [p(0,0), p(5,0), p(5,5), p(0,5)], color: GRAY });
outline.setFillOpacity(0);
outline.setStrokeWidth(1.5);

// --- Labels ---
const lblSq = new MathTex({ latex: 'x^2' });
await lblSq.waitForRender();
lblSq.moveTo(p(1, 1));

const lblR = new MathTex({ latex: '3x' });
await lblR.waitForRender();
lblR.moveTo(p(3.5, 1));

const lblT = new MathTex({ latex: '3x' });
await lblT.waitForRender();
lblT.moveTo(p(1, 3.5));

const lblC = new MathTex({ latex: '9' });
await lblC.waitForRender();
lblC.moveTo(p(3.5, 3.5));

const lblXb = new MathTex({ latex: 'x' });
await lblXb.waitForRender();
lblXb.moveTo([p(1,0)[0], A[1] - 0.4, 0]);

const lbl3b = new MathTex({ latex: '3' });
await lbl3b.waitForRender();
lbl3b.moveTo([p(3.5,0)[0], A[1] - 0.4, 0]);

const lblXl = new MathTex({ latex: 'x' });
await lblXl.waitForRender();
lblXl.moveTo([A[0] - 0.4, p(0,1)[1], 0]);

const lbl3l = new MathTex({ latex: '3' });
await lbl3l.waitForRender();
lbl3l.moveTo([A[0] - 0.4, p(0,3.5)[1], 0]);

const title = new Text({ text: 'Completing the Square', color: WHITE, fontSize: 40 });
title.moveTo([0, 3.2, 0]);

const eq1 = new MathTex({ latex: 'x^2 + 6x' });
await eq1.waitForRender();
eq1.scale(0.9);
eq1.moveTo([3.3, 1.4, 0]);

// --- Live layout updater ---
function layout(xv) {
  curX = xv;
  square.setVertices([p(0,0), p(xv,0), p(xv,xv), p(0,xv)]);
  rightRect.setVertices([p(xv,0), p(xv+3,0), p(xv+3,xv), p(xv,xv)]);
  topRect.setVertices([p(0,xv), p(xv,xv), p(xv,xv+3), p(0,xv+3)]);
  corner.setVertices([p(xv,xv), p(xv+3,xv), p(xv+3,xv+3), p(xv,xv+3)]);
  outline.setVertices([p(0,0), p(xv+3,0), p(xv+3,xv+3), p(0,xv+3)]);
  lblSq.moveTo(p(xv/2, xv/2));
  lblR.moveTo(p(xv + 1.5, xv/2));
  lblT.moveTo(p(xv/2, xv + 1.5));
  lblC.moveTo(p(xv + 1.5, xv + 1.5));
  lblXb.moveTo([p(xv/2, 0)[0], A[1] - 0.4, 0]);
  lbl3b.moveTo([p(xv + 1.5, 0)[0], A[1] - 0.4, 0]);
  lblXl.moveTo([A[0] - 0.4, p(0, xv/2)[1], 0]);
  lbl3l.moveTo([A[0] - 0.4, p(0, xv + 1.5)[1], 0]);
}

// --- Animated build-up ---
await scene.play(new Write(title));
await scene.play(new Write(eq1));
await scene.play(new DrawBorderThenFill(square));
await scene.play(new AnimationGroup([new FadeIn(lblSq), new FadeIn(lblXb), new FadeIn(lblXl)]));
await scene.play(new AnimationGroup([new DrawBorderThenFill(rightRect), new DrawBorderThenFill(topRect)]));
await scene.play(new AnimationGroup([new FadeIn(lblR), new FadeIn(lblT), new FadeIn(lbl3b), new FadeIn(lbl3l)]));
await scene.wait(0.4);
await scene.play(new AnimationGroup([new FadeIn(corner), new Create(outline)]));
await scene.play(new FadeIn(lblC));
await scene.wait(0.4);

const eq2 = new MathTex({ latex: 'x^2 + 6x + 9 = (x + 3)^2' });
await eq2.waitForRender();
eq2.scale(0.9);
eq2.moveTo([3.3, 1.4, 0]);
await scene.play(new FadeOut(eq1));
await scene.play(new Write(eq2));

const hint = new Text({ text: 'Drag the slider to change x', color: GRAY, fontSize: 22 });
hint.moveTo([3.3, 0.5, 0]);
await scene.play(new FadeIn(hint));

// --- Interactive controls ---
const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'x', min: 1, max: 3.5, value: 2, step: 0.1, onChange: (v) => { layout(v); } });
controls.addCheckbox({ label: 'Show missing corner (+9)', checked: true, onChange: (checked) => {
  if (checked) {
    scene.add(corner);
    scene.add(lblC);
  } else {
    scene.remove(corner);
    scene.remove(lblC);
  }
} });

await scene.wait(999999);"}

